import math, statistics

# How many subscribers rated each film (popular films say little about you)
support = {"Blockbuster": 200_000, "Hit": 90_000, "Cult": 900, "Obscure": 40}
wt = {m: 1 / math.log(n) for m, n in support.items()}

# Anonymised records: film -> (stars, day number)
records = {
    "r1": {"Blockbuster": (5, 10), "Hit": (4, 40)},
    "r2": {"Blockbuster": (5, 12), "Cult": (2, 95), "Obscure": (4, 130)},
    "r3": {"Blockbuster": (4, 11), "Hit": (4, 41), "Cult": (3, 300)},
    "r4": {"Hit": (5, 200), "Obscure": (1, 20)},
}
# What the attacker knows from public reviews: approximate stars and dates
aux = {"Blockbuster": (5, 20), "Cult": (2, 100), "Obscure": (4, 120)}

def score(rec):
    s = 0.0
    for film, (stars, day) in aux.items():
        if film in rec:
            s2, d2 = rec[film]
            s += wt[film] * (math.exp(-abs(stars - s2) / 1.5) + math.exp(-abs(day - d2) / 30))
    return s

scores = {r: round(score(rec), 3) for r, rec in records.items()}
print(scores)
top, second = sorted(scores.values(), reverse=True)[:2]
ecc = (top - second) / statistics.pstdev(scores.values())
print("eccentricity", round(ecc, 2), "-> match" if ecc >= 1.5 else "-> no match")

# Output:
# {'r1': 0.141, 'r2': 0.881, 'r3': 0.178, 'r4': 0.046}
# eccentricity 2.12 -> match

import ipaddress

# Each field records the purposes it was collected for
SCHEMA = {
    "email":     {"account", "billing"},
    "route_gps": {"show_my_runs"},
    "city":      {"show_my_runs", "product_analytics"},
    "ip_prefix": {"fraud"},
}

class PurposeError(Exception):
    pass

def read(record: dict, fields: list, purpose: str) -> dict:
    for f in fields:
        if purpose not in SCHEMA[f]:
            raise PurposeError(f"{f} was not collected for {purpose}")
    return {f: record[f] for f in fields}

def coarsen_ip(ip: str) -> str:                       # minimise at the point of collection
    return str(ipaddress.ip_network(ip + "/24", strict=False))

user = {"email": "ana@example.org", "route_gps": [(42.37612, -71.11638)],
        "city": "Cambridge", "ip_prefix": coarsen_ip("203.0.113.77")}

print(read(user, ["city"], "product_analytics"))
print(user["ip_prefix"])
try:
    read(user, ["route_gps"], "product_analytics")
except PurposeError as e:
    print("blocked:", e)

# Output:
# {'city': 'Cambridge'}
# 203.0.113.0/24
# blocked: route_gps was not collected for product_analytics

